using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a source-gen context that only knows about WeatherForecast.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default,
    WriteIndented = true
};

// 1) Strongly-typed retrieval — GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"Got JsonTypeInfo<WeatherForecast>  →  Type = {typedInfo.Type.Name}");

var forecast = new WeatherForecast("Seattle", 18);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");
Console.WriteLine();

// 2) Probe without throwing — TryGetTypeInfo returns false when metadata is absent.
bool found = options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? info);
Console.WriteLine($"TryGetTypeInfo(WeatherForecast) → found={found}, info is null={info is null}");

bool notFound = options.TryGetTypeInfo(typeof(UnknownDto), out JsonTypeInfo? missing);
Console.WriteLine($"TryGetTypeInfo(UnknownDto)       → found={notFound}, info is null={missing is null}");

// Types -----------------------------------------------------------------------
public record WeatherForecast(string City, int TempC);
public record UnknownDto(int Id);           // not registered in the context

[JsonSerializable(typeof(WeatherForecast))]
partial class AppJsonContext : JsonSerializerContext;

